//! Canonical tool identity.
//!
//! `ToolId`, its wire names, family, CLI-only and beta policy are generated by
//! build.rs from the embedded contract (core `TOOL_POLICIES`); this module only
//! adds runtime-owned behavior on top.

use std::str::FromStr;

/// Family used to partition cursor scope digests and remote/local policy.
///
/// Toggling local-only config (e.g. `allowed_paths`) must not invalidate
/// GitHub/remote cursors, so each family scopes its digest differently.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ToolFamily {
    /// Local-filesystem tools: scoped by cwd, allowed paths, and LSP config.
    Local,
    /// GitHub API tools: scoped by API endpoint + home, not local config.
    GitHub,
    /// Other remote tools (artifact, clasify): scoped by home only.
    Remote,
}

include!(concat!(env!("OUT_DIR"), "/tool_ids.rs"));

/// The contract's exit class of `code` (`errorCodes`). An undeclared code,
/// which the output contract already rejects, is an execution failure.
#[must_use]
pub fn error_class(code: &str) -> error_codes::ErrorClass {
    error_codes::parse(code).map_or(error_codes::ErrorClass::Unservable, error_codes::class)
}

/// The declared `errorCode` of a row's `data`; `None` when it has none (or
/// an undeclared one, which the output contract already rejects).
#[must_use]
pub fn error_code_of(data: &serde_json::Value) -> Option<octocode_contract_types::ErrorCode> {
    data.get("errorCode")
        .and_then(serde_json::Value::as_str)
        .and_then(error_codes::parse)
}

impl ToolId {
    /// Resolve a wire name to its identity, or `None` for an unknown tool.
    #[must_use]
    pub fn from_name(name: &str) -> Option<Self> {
        Self::ALL.into_iter().find(|id| id.as_str() == name)
    }

    /// The cross-tool calls this tool's served description promises as its
    /// `related` output (artifactSearch: the advisory lead of an exact row;
    /// graphBuild: the queries of the snapshot it published; graphQuery: the
    /// lspSearch check of a symbol answer's syntax rows).
    /// The response stage keeps a promised call by that promise alone; a
    /// contract-lock test pins each target to the producing description.
    #[must_use]
    pub(crate) const fn promised_links(self) -> &'static [Self] {
        match self {
            Self::ArtifactSearch => &[Self::SecurityCheck],
            Self::GraphBuild => &[Self::GraphQuery],
            Self::GraphQuery => &[Self::LspSearch],
            _ => &[],
        }
    }

    /// The diagnostic codes whose recovery this tool's output reference
    /// states once, as the row's related call to this tool, so a note of
    /// such a code carries no `recovery` of its own (astSearch: the related
    /// rule with `any` beside `structural.pattern.qualified`). The response
    /// stage keeps that call by the code alone; a contract-lock test pins
    /// each code to the producing reference.
    #[must_use]
    pub(crate) const fn codes_promising_related(self) -> &'static [&'static str] {
        match self {
            Self::AstSearch => &[
                "structural.pattern.qualified",
                "structural.rule.otherKind",
                "structural.rule.neighbor",
            ],
            _ => &[],
        }
    }

    /// A local-filesystem tool (honours local policy + allowed paths).
    #[must_use]
    pub const fn is_local(self) -> bool {
        matches!(self.family(), ToolFamily::Local)
    }

    /// A GitHub API tool (includes `ghCloneRepo`; clone has an extra gate).
    #[must_use]
    pub const fn is_github(self) -> bool {
        matches!(self.family(), ToolFamily::GitHub)
    }

    /// The public semantic assessment tool (beta plus a non-blank provider key).
    #[must_use]
    pub const fn is_clasify(self) -> bool {
        matches!(self, Self::Clasify)
    }

    /// Independent queries may execute concurrently; clasify owns its bounded scheduler.
    /// Clone rows run at once: each holds its entry's lock for all of its
    /// work (a cache hit or a fresh checkout, until the row returns), the
    /// lock other processes share, so rows for one entry serialize; eviction
    /// removes only entries whose lock it takes, so it never deletes another
    /// row's checkout; stages, askpass helpers and their names are per row.
    #[must_use]
    pub const fn supports_concurrent_queries(self) -> bool {
        !matches!(self, Self::Clasify)
    }

    /// Each row carries one source `content` string a caller copies from
    /// (numbered lines, sized to its share of the response page).
    #[must_use]
    pub(crate) const fn reads_source(self) -> bool {
        matches!(self, Self::LocalFetch | Self::GhGetFileContent)
    }

    /// Whether `classification` selects this tool's rows at the shared response
    /// boundary, over one sanitized provider page (code search, history, structure), instead of
    /// before the tool's own source pagination.
    #[must_use]
    pub const fn selects_provider_page(self) -> bool {
        matches!(
            self,
            Self::GhSearchCode
                | Self::GhSearchHistory
                | Self::GhGetHistoryItem
                | Self::StructureSearch
        )
    }

    /// The scope and unit of the selection receipt a classified row of this
    /// tool carries: the hits of one provider page
    /// ([`Self::selects_provider_page`]), the hits of a search's view, or the
    /// chunks of the view a reader selects from; `None` for a tool whose rows
    /// are never classified.
    #[must_use]
    pub const fn selection_receipt(
        self,
    ) -> Option<(
        octocode_contract_types::SelectionScope,
        octocode_contract_types::SelectionUnit,
    )> {
        use octocode_contract_types::{SelectionScope, SelectionUnit};
        if self.selects_provider_page() {
            return Some((SelectionScope::ProviderPage, SelectionUnit::Hits));
        }
        match self {
            // A search's units are its hits (`local_search::selection`).
            Self::LocalSearch => Some((SelectionScope::SelectedView, SelectionUnit::Hits)),
            // A read's units are the hits of a search it follows, else the
            // chunks of its view: a read that failed before choosing says
            // the broader, chunks.
            Self::LocalFetch | Self::GhGetFileContent => {
                Some((SelectionScope::SelectedView, SelectionUnit::Chunks))
            }
            _ => None,
        }
    }

    /// Row members carried by a split row's first part only, stated once
    /// for the whole row: its notices (`warnings`) and the receipt of the
    /// scan that found it (`filesScanned`); clasify rows are keyed query
    /// results that also state their questions once. The output schema
    /// requires none of them, so a later part without them is valid.
    #[must_use]
    pub(crate) const fn first_fragment_fields(self) -> &'static [&'static str] {
        match self {
            Self::Clasify => &["/data/questions", "/data/warnings", "/data/filesScanned"],
            _ => &["/data/warnings", "/data/filesScanned"],
        }
    }
}

impl FromStr for ToolId {
    type Err = ();

    fn from_str(value: &str) -> Result<Self, Self::Err> {
        Self::from_name(value).ok_or(())
    }
}

impl std::fmt::Display for ToolId {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str(self.as_str())
    }
}

/// The name of the `index`th (from 0) continuation of `kind` on one row:
/// `kind` itself, then `kind2`, `kind3`, …; `kind` is its inverse.
pub fn numbered(kind: &str, index: usize) -> String {
    match index {
        0 => kind.to_owned(),
        index => format!("{kind}{}", index + 1),
    }
}

